import{_ as n,o as t,c as r,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const h=JSON.parse('{"title":"Symbol, Farbe und Kategorie","description":"Spaces mit Symbol, Farbe und Kategorie unterscheidbar machen.","frontmatter":{"title":"Symbol, Farbe und Kategorie","description":"Spaces mit Symbol, Farbe und Kategorie unterscheidbar machen."},"headers":[],"relativePath":"spaces/symbol-und-farbe.md","filePath":"spaces/symbol-und-farbe.md","lastUpdated":1786092153000}'),a={name:"spaces/symbol-und-farbe.md"};function s(o,e,l,d,c,b){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="symbol-farbe-und-kategorie" tabindex="-1">Symbol, Farbe und Kategorie <a class="header-anchor" href="#symbol-farbe-und-kategorie" aria-label="Permalink to &quot;Symbol, Farbe und Kategorie&quot;">​</a></h1><p>Bei mehreren Spaces hilft optische Unterscheidung mehr als jede Sortierung. Symbol und Farbe erscheinen in der Übersicht und in der Navigation.</p><h2 id="symbol-setzen" tabindex="-1">Symbol setzen <a class="header-anchor" href="#symbol-setzen" aria-label="Permalink to &quot;Symbol setzen&quot;">​</a></h2><p>Über <strong>Icon &amp; Farbe festlegen</strong> öffnet sich der Symbolwähler:</p><table tabindex="0"><thead><tr><th>Element</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Icon Suche</strong></td><td>Durchsucht die verfügbaren Symbole</td></tr><tr><td><strong>Transparenter Hintergrund</strong></td><td>Symbol ohne farbige Hinterlegung</td></tr><tr><td><strong>Icon-Datei hochladen</strong></td><td>Eigenes Bild als Symbol</td></tr><tr><td><strong>Zurücksetzen</strong></td><td>Entfernt das Symbol wieder</td></tr></tbody></table><p>Für eigene Symbole gilt der Hinweis <em>Bild hier ablegen… oder klicken zum Durchsuchen</em>. Ist bereits eines gesetzt, heißen die Aktionen <strong>Icon-Datei ändern</strong> und <strong>Icon-Datei entfernen</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Symbole nach Funktion, nicht nach Geschmack</p><p>Nützlich wird das erst, wenn die Symbole etwas bedeuten: alle Kunden-Spaces ein Symbol, alle internen ein anderes, das Archiv ein drittes. Zwanzig hübsche, aber beliebige Symbole helfen beim Suchen nicht.</p></div><div class="tip custom-block"><p class="custom-block-title">Eigenes Symbol für Kundenprojekte</p><p>Für Spaces, die ein Kunde über ein <a href="/docs/seiten/portal-veroeffentlichen">Portal</a> zu sehen bekommt, lohnt sich das Kundenlogo als Icon-Datei — hilfreich für alle, die mit mehreren Kunden parallel arbeiten.</p></div><h2 id="farbe-setzen" tabindex="-1">Farbe setzen <a class="header-anchor" href="#farbe-setzen" aria-label="Permalink to &quot;Farbe setzen&quot;">​</a></h2><p>Im selben Dialog wählen Sie eine Farbe. Der Farbwähler merkt sich zuletzt verwendete Farben unter <strong>Gespeicherte Farben</strong>; über <strong>Hinzufügen</strong> legen Sie die aktuelle Farbe dort ab.</p><p>Ohne gespeicherte Farben steht dort: <em>Keine gespeicherten Farben. Klicken Sie auf „Hinzufügen&quot;, um die aktuelle Farbe zu speichern.</em></p><div class="warning custom-block"><p class="custom-block-title">Farben sind tarifabhängig</p><p>Space-Farben stehen nicht in allen Tarifen zur Verfügung. Symbole sind davon nicht betroffen.</p></div><div class="tip custom-block"><p class="custom-block-title">Farbe als System</p><p>Am nützlichsten ist eine Farbe, die einen Zustand ausdrückt — etwa Grün für aktive Projekte, Grau für abgeschlossene. Beim Wechsel des Zustands ändern Sie die Farbe, und die Übersicht bleibt aussagekräftig.</p></div><h2 id="kategorie-zuordnen" tabindex="-1">Kategorie zuordnen <a class="header-anchor" href="#kategorie-zuordnen" aria-label="Permalink to &quot;Kategorie zuordnen&quot;">​</a></h2><p>Eine <strong>Kategorie</strong> bündelt Spaces in der Übersicht. Über <strong>Nach Kategorie gruppieren</strong> schalten Sie die Gruppierung ein; Spaces ohne Zuordnung stehen unter <em>Keine Kategorie</em>.</p><p>Anders als Symbol und Farbe wirkt die Kategorie strukturierend, nicht nur optisch.</p><div class="tip custom-block"><p class="custom-block-title">Wenige, klare Kategorien</p><p>Drei bis fünf reichen fast immer: „Kunden&quot;, „Intern&quot;, „Archiv&quot;. Zu viele Kategorien sind so unübersichtlich wie keine.</p></div><h2 id="auch-fur-ansichten-und-seiten" tabindex="-1">Auch für Ansichten und Seiten <a class="header-anchor" href="#auch-fur-ansichten-und-seiten" aria-label="Permalink to &quot;Auch für Ansichten und Seiten&quot;">​</a></h2><p>Symbol und Farbe gibt es nicht nur für Spaces:</p><ul><li><strong>Seiten</strong> — über <em>Icon &amp; Farbe festlegen</em> im Seitenmenü</li><li><strong>Ansichten</strong> — dieselbe Funktion, allerdings nur bei eingeschaltetem Beta-Modus</li></ul><div class="warning custom-block"><p class="custom-block-title">Bei Ansichten eine Vorabfunktion</p><p>Symbol und Farbe für Ansichten erscheinen nur, wenn im Profil die Vorabfunktionen aktiviert sind (<em>Teste unsere neuesten Funktionen</em>). Verlassen Sie sich in Anleitungen für Ihr Team nicht darauf — die Funktion kann sich ändern.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/spaces/space-anlegen">Space anlegen</a></li><li><a href="/docs/spaces/navigation">Navigation einrichten</a></li><li><a href="/docs/seiten/seite-erstellen">Seite erstellen und bearbeiten</a></li></ul>',23)])])}const m=n(a,[["render",s]]);export{h as __pageData,m as default};
